HELP_TOPICS = {'mode_border_plate': {'title': 'Forma base: Marco (Border) vs. Placa / Inlay (Plate)', 'short': 'Alterna entre un marco abierto (Border) y una placa continua de metal o cristal (Plate).', 'detail': '• MARCO (Border): el centro queda abierto (transparente) para enmarcar su foto o diseño.\n• PLACA / INLAY (Plate): el centro se rellena como placa metálica cepillada, vidrio semitransparente o lecho de inlay de color (ideal para logotipos, insignias y placas).'}, 'grow_direction': {'title': 'Dirección de crecimiento (Exterior, Interior, Ambos)', 'short': 'Controla si el marco crece hacia afuera, hacia adentro o centrado sobre el borde de la selección.', 'detail': '• Hacia afuera (Ampliar imagen): el marco se construye fuera de la selección. Si falta margen, Borderlay amplía automáticamente el lienzo de GIMP.\n• Hacia adentro: el marco crece desde el borde hacia el centro.\n• Ambos (Centrado): el marco cabalga sobre el borde (50 % afuera, 50 % adentro).'}, 'corner_radii': {'title': 'Esquinas y radios (Radio exterior e interior)', 'short': 'Controla el redondeo de las esquinas exteriores e interiores (0 px = inglete vivo de 45°).', 'detail': '• Suave / Medio / Sutil (Radio > 0 px): crea esquinas concéntricas redondeadas como una placa estampada.\n• Inglete de 45° (0 / 0 px): crea un marco clásico con esquinas de 90° y uniones diagonales reales de 45°.\n• En la pestaña «2. Geometría, radios y 3D» puede ajustar ambos radios por separado en píxeles.'}, 'shape_toolbox': {'title': 'Formas de selección y alineación', 'short': 'Establece una forma como selección y la alinea. No renderiza marco.', 'detail': '• Toque una categoría arriba. Cada forma es una ficha con su identificador debajo (p. ej. leaf.heart), también seleccionable bajo la vista previa grande.\n• Tamaño, ángulo y parámetros dibujan la forma de inmediato con color sobre la imagen.\n• Aplicar quita el color y fija la selección. Cerrar sin aplicar quita el color y restaura la selección anterior.\n• Look incluye formas básicas, una onda y una sonrisa.\n• Atelier y Team añaden llamas, engranajes, hojas, ornamento, motivos festivos, arcos, parámetros de onda, guiño y ángulo previo.\n• Una selección rectangular define el marco de colocación: la forma inicia centrada según su proporción. Sin selección inicia centrada al 60 % del lado corto.\n• Alinear ajusta la forma a ese marco; las flechas la mueven por pasos en píxeles incluso fuera del marco. Se mueve la forma, no una capa.'}, 'shape_rotation': {'title': 'Rotar forma de selección (Ángulo y eje pivote de 9 puntos)', 'short': 'Rota solo la geometría del marco alrededor del pivote elegido — ¡la imagen permanece intacta!', 'detail': '• Ángulo (-180° a +180°): rota la geometría del marco o placa.\n• Hoja: punta arriba, tallo abajo. El pivote «borde inferior centro» sitúa el tallo en el centro de la roseta.\n• Eje pivote: define el punto de anclaje (Centro, Esquina superior izquierda, etc.).\n• Importante: su foto NO se rota y la iluminación global sigue siendo coherente.'}, 'repeat_rotation': {'title': 'Rotación repetida (Ángulo 1 -> Ángulo 2, paso y desvanecimiento)', 'short': 'Genera automáticamente una serie rotada (abanico / caleidoscopio) con fundido progresivo.', 'detail': '• Ángulo inicial 1 y final 2 (°): define el rango angular de repetición.\n• Paso de rotación (°): intervalo angular entre copias.\n• Ciclos: repite el ciclo desplazando ligeramente cada pasada con fundido continuo.\n• o hasta ángulo: 0 usa solo los ciclos; un ángulo mayor continúa el paso mientras ciclos esté en 1.\n• Pasos de fundido (%): atenúa suavemente la opacidad desde la primera copia (100 %) hasta la última.'}, 'inlay_color': {'title': 'Color de cristal e inlay (incl. cuentagotas y muestras)', 'short': 'Define el color propio para «Cristal de color» y para los surcos y placas inlay.', 'detail': '¿Dónde actúa este color?\n1. Con «Cristal de color», tiñe todo el cuerpo de vidrio y su refracción.\n2. Con «Cavidad inlay coloreada» en modo Placa, tiñe el espejo interior.\n3. En el Editor multizona, colorea las zonas ajustadas a «Color Inlay (inlay)».\n\nConsejo: pulse la barra de color para abrir la rueda y el cuentagotas o elija una de las 8 gemas.'}, 'metal_gradient': {'title': 'Degradado metálico y anchura de transición', 'short': 'Elige entre la curva física de aleación de 7 puntos y degradados nativos de GIMP.', 'detail': '• Curva interna de 7 puntos (Recomendado): calcula la reflexión física de cada metal.\n• Degradado GIMP: sustituye la curva por un degradado de GIMP.\n• Ajuste la transición entre pendientes y mesetas con «Suavidad del bisel (%)».'}, 'dual_profile_cut': {'title': 'Corte transversal interactivo y anchura de transición', 'short': 'Muestra en vivo dónde actúan colores de zona, surcos, opacidad de placa y transiciones.', 'detail': '• El corte muestra el perfil de elevación del borde exterior (izquierda) a la zona interior (derecha).\n• A la derecha indica en vivo si el centro queda abierto o con placa a la opacidad elegida (%).\n• Las bandas amarillas marcan la anchura de transición activa («Suavidad del bisel»).\n• En la pestaña 5, haga clic en Z1..Zn en el gráfico para enfocar la fila de zona correspondiente.'}, 'light_vector': {'title': 'Vector de luz 2D, tipo de fuente (Haz vs. Cono) e impacto', 'short': 'Controla gráficamente origen -> impacto, ángulo (°), intensidad (%) y ancho/diámetro.', 'detail': '• Arrastre en el panel 2D desde el punto amarillo de origen hasta la punta de flecha:\n  - La dirección define el ángulo de incidencia (0°–360°, defecto 135°).\n  - La longitud controla la intensidad especular (%).\n• Cono de luz (Cono): foco con diámetro de cono ajustable (%).\n• Haz de luz (Haz): banda lineal suave con anchura ajustable (%).'}, 'inner_shimmer': {'title': 'Brillo interior que sigue el contorno', 'short': 'Proyecta un suave resplandor metálico desde el borde interior del marco hacia el centro.', 'detail': 'El brillo interior abraza el contorno más interno y puede seguir la luz principal, iluminar arriba-izquierda, a contraluz (abajo-derecha) o alrededor.'}, 'surface_finish': {'title': 'Acabado: Cepillado, Grano, Plumas, Pelo y Escamas', 'short': 'Controla el acabado desde Espejo y Satinado hasta Cepillado, Grano, Plumas, Pelo y Escamas.', 'detail': '• Espejo / Satinado: brillo limpio o acabado satinado suave.\n• Cepillado: líneas finas direccionales con grosor y ángulo ajustables.\n• Grano: microtextura uniforme sin líneas de cepillado.\n• Plumas, Pelo y Escamas: texturas orgánicas con tamaño, longitud, densidad y dirección.\n• Dirección «Sigue la luz» (-1) o cualquier ángulo fijo (0° = derecha).'}, 'lighting_glow': {'title': 'Efectos de luz, Brillo y Resplandor (Bloom)', 'short': 'Controla luz automática, brillo especular, resplandor suave (Bloom), contraste de bisel y brillo interior.', 'detail': '• Luz automática (desde Community) o panel 2D Cono/Haz (Atelier).\n• Brillo y Resplandor (Bloom): crean un halo suave en los reflejos.\n• Contraste de bisel y brillo interior: realzan el volumen 3D.'}, 'support': {'title': 'Soporte', 'short': 'El soporte se ofrece solo para Look, Atelier y Team.', 'detail': 'El soporte se ofrece solo para Look, Atelier y Team.\nContacto: https://www.ready-4-it.com/contact'}}
